SELECT country, CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values, SORT_ARRAY(COLLECT_SET(country)) AS country_list, ROUND(STDDEV(rating), 2) AS stddev_rating FROM suppliers GROUP BY country, CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END
